"""
Recognising which motion library a TwinCAT project uses.

pytmc works with two motion libraries: the legacy ``lcls-twincat-motion``
(namespace ``lcls_twincat_motion``) and the new
``lcls-twincat-motion-abstraction`` (namespace ``LCLS_Tc_Motion``, with other
names during its development). Code whose behavior depends on the library
should ask here instead of testing for a type or a pragma on its own.

Two independent signals mark the new library, and either is enough:

* **Namespace**: a symbol whose data type is qualified with a new-library
  namespace, e.g. ``LCLS_Tc_Motion.ST_PositionState``. The TMC carries it, so
  this also works where only a TMC is available (``pytmc db``).
* **NC-mapped motors**: an ``FB_MotionStage`` symbol (``FB_MotionStageNC`` and
  its variants) with a pytmc pragma carrying ``axis-link:``. These are the
  motors ``pytmc template`` generates st.cmd entries for.

Use the function that matches what you have: a data type, a symbol, or a TMC.
"""

import logging

from . import parser

logger = logging.getLogger(__name__)

# Namespaces of the new library, including the names it had during its
# development. Compared case-insensitively.
NEW_LIBRARY_NAMESPACES = (
    "LCLS_Tc_Motion",
    "LCLS_MotionAbstraction",
    "LCLS_OOPMotion",
)


def is_new_library_type(data_type) -> bool:
    """
    True if ``data_type`` is from the new motion library, going by the
    namespace in its qualified name (``LCLS_Tc_Motion.ST_PositionState``).
    A type with no namespace is not recognised.
    """
    qualified = getattr(data_type, "qualified_type_name", None) or ""
    namespace, dot, _ = qualified.partition(".")
    return bool(dot) and namespace.lower() in {
        known.lower() for known in NEW_LIBRARY_NAMESPACES
    }


def is_nc_mapped_motor(symbol) -> bool:
    """
    True if ``symbol`` is a motor of the new library with an NC mapping: an
    ``FB_MotionStage`` (not a pointer) with a pytmc pragma carrying
    ``axis-link:``. Only these get a motor record and an st.cmd entry.
    """
    return (
        isinstance(symbol, parser.Symbol_FB_MotionStage)
        and not symbol.is_pointer
        and parser.has_pragma(symbol)
        and parser.has_axis_link(symbol)
    )


def is_legacy_motor(symbol) -> bool:
    """True if ``symbol`` is a motor (not a pointer) of the legacy library."""
    return isinstance(symbol, parser.Symbol_ST_MotionStage) and not symbol.is_pointer


def is_new_library_symbol(symbol) -> bool:
    """
    True if ``symbol`` is of the new motion library: its data type is from a
    new-library namespace, or it is an NC-mapped motor
    (see :func:`is_nc_mapped_motor`).
    """
    try:
        if is_new_library_type(symbol.data_type):
            return True
    except Exception:
        # Detection is best effort: a type that cannot be resolved is not
        # evidence of either library
        logger.debug("No data type for %s", getattr(symbol, "name", symbol))

    return is_nc_mapped_motor(symbol)


def uses_new_library(tmc) -> bool:
    """True if any symbol of the TMC is of the new motion library."""
    return any(is_new_library_symbol(symbol) for symbol in tmc.find(parser.Symbol))
